{
  "name": "TTI PL330P直流电源",
  "name_en": "TTI PL330P DC Power Supply",
  "manufacturer": "Thurlby Thandar",
  "description": "TTI PL330P 是一款可编程台式直流电源，输出范围为 0–32 V、0–3 A。它用于为实验电路、模块或原型提供可调直流电压与电流，并可远程控制输出开关。",
  "description_en": "The TTI PL330P is a programmable bench DC power supply with a 0–32 V, 0–3 A output range. It is used to provide adjustable DC voltage and current to laboratory circuits, modules, or prototypes, with remote control of the output state.",
  "actions": [
    {
      "action_name": "auto-volts",
      "description": "获取/设置/定义输出电压",
      "description_en": "get/set/define output voltage"
    },
    {
      "action_name": "auto-current",
      "description": "获取/设置/定义输出电流设定",
      "description_en": "get/set/define output current setting"
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置/定义输出开关状态",
      "description_en": "get/set/define output state"
    }
  ],
  "tag_hints": [
    "DC power supply",
    "bench PSU",
    "programmable voltage",
    "current limiting",
    "GPIB control",
    "0-32 V output",
    "0-3 A output"
  ]
}

